import { describe, expect, it } from "vitest";
import { lookupDriver, loldriversUrl, type DriverData } from "./logic";

// Hand-built fixture; the real catalog is generated by scripts/update-loldrivers.mjs.
const DATA: DriverData = {
  count: 2,
  drivers: [
    {
      id: "aaaa-1111",
      category: "vulnerable driver",
      author: "Someone",
      samples: [
        {
          filename: "RTCore64.sys",
          md5: "2d8e4f38b36c334d0a32a7324832501d",
          sha1: "f6f11ad2cd2b0cf95ed42324876bee1d83e01775",
          sha256: "01aa278b07b58dc46c84bd0b1b5c8e9ee4e62ea0bf7a695862444af32e87f1fd",
          hvci: false,
        },
      ],
    },
    {
      id: "bbbb-2222",
      category: "malicious",
      author: "Nobody",
      samples: [
        {
          filename: "evil.sys",
          md5: "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
          sha1: "",
          sha256: "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb0",
          hvci: true,
        },
      ],
    },
  ],
  hashes: {
    "2d8e4f38b36c334d0a32a7324832501d": 0,
    f6f11ad2cd2b0cf95ed42324876bee1d83e01775: 0,
    "01aa278b07b58dc46c84bd0b1b5c8e9ee4e62ea0bf7a695862444af32e87f1fd": 0,
    aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa: 1,
    bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb0: 1,
  },
  names: { "rtcore64.sys": [0], "evil.sys": [1] },
};

describe("lookupDriver", () => {
  it("is empty for blank input", () => {
    expect(lookupDriver("  ", DATA).kind).toBe("empty");
  });

  it("finds a driver by SHA-256 and reports the matched sample", () => {
    const r = lookupDriver("01AA278B07B58DC46C84BD0B1B5C8E9EE4E62EA0BF7A695862444AF32E87F1FD", DATA);
    expect(r.kind).toBe("hash");
    expect(r.matches).toHaveLength(1);
    expect(r.matches[0].driver.category).toBe("vulnerable driver");
    expect(r.matches[0].matchedSample?.filename).toBe("RTCore64.sys");
  });

  it("finds a driver by MD5 and SHA-1 too", () => {
    expect(lookupDriver("2d8e4f38b36c334d0a32a7324832501d", DATA).matches[0].driver.id).toBe("aaaa-1111");
    expect(lookupDriver("f6f11ad2cd2b0cf95ed42324876bee1d83e01775", DATA).matches[0].driver.id).toBe("aaaa-1111");
  });

  it("finds a malicious driver and preserves the HVCI flag", () => {
    const r = lookupDriver("aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", DATA);
    expect(r.matches[0].driver.category).toBe("malicious");
    expect(r.matches[0].matchedSample?.hvci).toBe(true);
  });

  it("looks up by filename, adding .sys when omitted", () => {
    expect(lookupDriver("RTCore64", DATA).matches[0].driver.id).toBe("aaaa-1111");
    expect(lookupDriver("rtcore64.sys", DATA).matches[0].driver.id).toBe("aaaa-1111");
  });

  it("returns no matches for an unknown hash (still classified as a hash query)", () => {
    const r = lookupDriver("ffffffffffffffffffffffffffffffff", DATA);
    expect(r.kind).toBe("hash");
    expect(r.matches).toEqual([]);
  });

  it("builds the loldrivers.io URL from an id", () => {
    expect(loldriversUrl("aaaa-1111")).toBe("https://www.loldrivers.io/drivers/aaaa-1111/");
  });
});
